const int ledPin = 13;

void setup() {
  pinMode(ledPin, OUTPUT); // Configure Pin 13 as a low-impedance output
}

void loop() {
  digitalWrite(ledPin, HIGH); // Turn LED ON (5V)
  delay(1000);                // Wait 1000 ms (1 second)
  digitalWrite(ledPin, LOW);  // Turn LED OFF (0V)
  delay(1000);                // Wait 1000 ms (1 second)
}
```
